\documentclass{article}
\usepackage{amsmath}
\usepackage{amssymb}
\usepackage{graphicx}

\begin{document}

\section*{Barometer to Sea Level}

\textit{Of two stations, the temperature being $t$, the barometer reading at lower station $b$, and at the upper station $b - \frac{1}{10}$. Hence, by (iii.),}

\begin{equation}
b^{N_t} = A_t \log \frac{b}{b - \frac{1}{10}}.
\end{equation}

\textit{Also $R$ being the reduction, (iii.) may be written}

\begin{equation}
Z = A_t \log \frac{\beta + R}{\beta}.
\end{equation}

\textit{Combining these, we get}

\begin{equation}
\log \left(1 + \frac{R}{\beta}\right) = \frac{Z}{b^{N_t}} \log \frac{10b}{10b - 1};
\end{equation}

\textit{hence,}

\begin{equation}
1 + \frac{R}{\beta} = \left(\frac{10b}{10b - 1}\right) \frac{Z}{b^{N_t}} = \left(1 - \frac{1}{10b}\right) - \frac{Z}{b^{N_t}}
\end{equation}

\begin{equation}
= 1 + \frac{Z}{b^{N_t}} \cdot \frac{1}{10b} + \frac{1}{1.2} \cdot \frac{Z}{b^{N_t}} \cdot \frac{Z}{b^{N_t}} + 1 \cdot \frac{1}{10b} \left| \frac{Z}{b^{N_t}} \right|^2 + \ldots
\end{equation}

\textit{by the binomial theorem.}

\begin{equation}
\therefore R = \beta \left( \frac{Z}{b^{N_t}} \cdot \frac{1}{10b} + \frac{1}{1.2} \cdot \frac{Z}{b^{N_t}} \cdot \frac{Z}{b^{N_t}} + 1 \cdot \frac{1}{10b} \left| \frac{Z}{b^{N_t}} \right|^2 + \ldots \right) \tag{iv.}
\end{equation}

\textit{Formula (i.) is deduced from (iv.), by neglecting all terms beyond the first; and making $b = 30$ inches, if used with Table XVI.; but, if used with Table XIX., $b$ may be any reading within the range of the table, and $b^{N_t}$ the corresponding number from the table.}

\textit{Although (i.) is sufficiently accurate for small heights, it is evident, on comparing it with the full formula (iv.), that it becomes more and more inaccurate as the height increases.}

\textit{If, in (i.), the reduced height $B$, were substituted for the observed height $\beta$, the error would be relatively less; for Laplace's formula may also be expanded in the form}

\begin{equation}
R = B \left( \frac{Z}{b^{N_t}} \cdot \frac{1}{10b} - \frac{1}{1.2} \cdot \frac{Z}{b^{N_t}} \cdot \frac{Z}{b^{N_t}} - 1 \cdot \frac{1}{10b} \left| \frac{Z}{b^{N_t}} \right|^2 + \ldots \right) \tag{v.}
\end{equation}

\end{document}
